/* 布局·手风琴 —— 默认折叠成标题条，悬停展开 */
body.l-accordion .hero { min-height: 82vh; }
body.l-accordion main section {
  max-height: 108px; overflow: hidden; cursor: pointer;
  border-top: 1.5px solid var(--border);
  padding-top: 30px; padding-bottom: 30px;
  transition: max-height .55s cubic-bezier(.2,.7,.2,1);
}
body.l-accordion main section:hover,
body.l-accordion main section:focus-within,
body.l-accordion main section:target { max-height: 2600px; }
body.l-accordion main section:last-of-type { border-bottom: 1.5px solid var(--border); }
body.l-accordion .section-title::after {
  content: "+"; float: right; color: var(--text-2); font-weight: 400;
  transition: transform .3s;
}
body.l-accordion main section:hover .section-title::after,
body.l-accordion main section:focus-within .section-title::after,
body.l-accordion main section:target .section-title::after { content: "−"; color: var(--accent); }
body.l-accordion .section-desc { margin-bottom: 26px; }
body.l-accordion .reveal { opacity: 1; transform: none; }
body.l-accordion main section::after {
  content: "导航 / 聚焦展开"; position: absolute; margin-top: -52px; right: 24px;
  font-size: 12px; color: var(--text-2); letter-spacing: 2px;
}
body.l-accordion main section:hover::after,
body.l-accordion main section:focus-within::after,
body.l-accordion main section:target::after { content: ""; }
body.l-accordion main section { position: relative; }
@media (max-width: 900px) {
  body.l-accordion nav .nav-inner { gap: 10px; }
  body.l-accordion nav .nav-links {
    display: flex; min-width: 0; margin-left: 0; gap: 8px;
    overflow-x: auto; scrollbar-width: thin;
  }
  body.l-accordion nav .nav-links a {
    flex: 0 0 auto; min-height: 44px; padding: 10px 12px;
    display: inline-flex; align-items: center; white-space: nowrap;
  }
  body.l-accordion nav .gallery-link { display: none; }
}
